def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = opp.count('D')
    my_d = me.count('D')

    if opp_d == 0:
        return 'C'

    if my_d > opp_d + 2:
        return 'C'

    if n < 10:
        if opp[-1] == 'D':
            if n >= 2 and opp[-2] == 'D':
                return 'D'
            return 'C'
        return 'C'

    if opp[-1] == 'D':
        recent = opp[-4:]
        recent_d = recent.count('D')
        if recent_d >= 2 or opp_d * 3 > n:
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        return 'C'
    else:
        if opp_d * 3 > n:
            if rng.random() < 0.8:
                return 'D'
            return 'C'
        return 'C'
